CREATE OR REPLACE FUNCTION public.fn_accounting_agent_terms_at(p_club_id uuid, p_user_id uuid, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE identities text[]; identity_key text; v jsonb; result jsonb; active_count int:=0;
BEGIN
 -- Service-only EXECUTE ACL also permits private source-owner triggers.
 IF p_club_id IS NULL OR p_user_id IS NULL OR p_at IS NULL OR NOT isfinite(p_at) OR p_at>transaction_timestamp()
 THEN RAISE EXCEPTION 'invalid_accounting_terms_request' USING ERRCODE='22023'; END IF;
 -- Find candidate identities from history, then resolve each identity at the
 -- earning time. A later move/deletion closes the old identity; filtering the
 -- history by club before selecting its latest event would resurrect that row.
 SELECT array_agg(DISTINCT entity_key) INTO identities FROM public.accounting_agreement_history
  WHERE entity_type='agents' AND club_id=p_club_id AND subject_user_id=p_user_id AND observed_at<=p_at;
 IF identities IS NULL THEN RAISE EXCEPTION 'accounting_terms_not_observed' USING ERRCODE='55000'; END IF;
 FOREACH identity_key IN ARRAY identities LOOP
  v:=public.fn_accounting_terms_at('agents',identity_key,p_at);
  IF v->'terms'->>'club_id'=p_club_id::text AND v->'terms'->>'user_id'=p_user_id::text
     AND v->'terms'->>'status'='active' THEN
   active_count:=active_count+1; result:=v;
  END IF;
 END LOOP;
 IF active_count=0 THEN RAISE EXCEPTION 'accounting_terms_not_active' USING ERRCODE='55000'; END IF;
 IF active_count>1 THEN RAISE EXCEPTION 'accounting_terms_ambiguous' USING ERRCODE='55000'; END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.fn_accounting_earning_contract(p_club_id uuid, p_player_id uuid, p_rake numeric, p_game_union_id uuid, p_terms_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE member jsonb;agent jsonb;terms jsonb;chain jsonb;remaining numeric;rate numeric;amount numeric;
 seen uuid[];agent_id uuid;parent_id uuid;agent_user uuid;direct_user uuid;union_count int;coordinator_union uuid;union_agreement jsonb;union_house boolean;
BEGIN
 -- Private EXECUTE grants admit only trusted source owners, including the
 -- registration trigger running for a human. Public wrappers verify actors.
 IF p_club_id IS NULL OR p_player_id IS NULL OR p_terms_at IS NULL OR NOT isfinite(p_terms_at) OR p_terms_at>clock_timestamp()
  OR p_rake IS NULL OR p_rake<0 OR p_rake<>round(p_rake,2) OR p_rake::text IN('NaN','Infinity','-Infinity')
 THEN RAISE EXCEPTION 'invalid_accounting_earning_contract' USING ERRCODE='22023'; END IF;
  SELECT count(*),(array_agg((uc.after_terms->>'union_id')::uuid))[1],
   (jsonb_agg(jsonb_build_object('history_id',uc.id,'observed_at',uc.observed_at,'terms',uc.after_terms)))->0
   INTO union_count,coordinator_union,union_agreement FROM (
    SELECT DISTINCT ON(h.entity_key) h.id,h.observed_at,h.after_terms FROM public.accounting_agreement_history h
     WHERE h.entity_type='union_clubs' AND h.club_id=p_club_id AND h.observed_at<=p_terms_at
     ORDER BY h.entity_key,h.observed_at DESC,h.id DESC) uc
    WHERE uc.after_terms IS NOT NULL AND uc.after_terms->>'club_id'=p_club_id::text;
  SELECT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=p_club_id AND c.is_union IS TRUE
   AND p_game_union_id IS NOT NULL AND (c.id=p_game_union_id OR c.union_id=p_game_union_id)) INTO union_house;
  IF union_house THEN coordinator_union:=p_game_union_id;union_agreement:=NULL; END IF;
  IF union_count>1 OR (p_game_union_id IS NOT NULL AND NOT union_house AND (union_count<>1 OR coordinator_union IS DISTINCT FROM p_game_union_id))
  THEN RAISE EXCEPTION 'cash_commission_earning_club_not_observed' USING ERRCODE='23514'; END IF;
  member:=public.fn_accounting_terms_at('club_members',p_club_id::text||':'||p_player_id::text,p_terms_at);
  terms:=member->'terms';
  IF terms IS NULL OR terms='null'::jsonb OR terms->>'club_id' IS DISTINCT FROM p_club_id::text OR terms->>'user_id' IS DISTINCT FROM p_player_id::text
   OR (terms->>'status' IS NULL OR terms->>'status' NOT IN('active','approved')) OR COALESCE((terms->>'is_active')::boolean,true)=false
  THEN RAISE EXCEPTION 'cash_commission_membership_not_active_at_earning' USING ERRCODE='23514'; END IF;
  direct_user:=NULLIF(terms->>'agent_id','')::uuid; agent:=NULL;
  IF direct_user IS NOT NULL THEN
   agent:=public.fn_accounting_agent_terms_at(p_club_id,direct_user,p_terms_at);
  ELSE
   BEGIN agent:=public.fn_accounting_agent_terms_at(p_club_id,p_player_id,p_terms_at);
   EXCEPTION WHEN SQLSTATE '55000' THEN
    IF SQLERRM IN('accounting_terms_not_observed','accounting_terms_not_active') THEN agent:=NULL; ELSE RAISE; END IF; END;
  END IF;
  remaining:=p_rake;chain:='[]';seen:=ARRAY[]::uuid[];
  WHILE agent IS NOT NULL AND agent->'terms' IS NOT NULL AND agent->'terms'<>'null'::jsonb LOOP
   terms:=agent->'terms'; agent_id:=(terms->>'id')::uuid;agent_user:=(terms->>'user_id')::uuid;
   IF agent_id IS NULL OR agent_user IS NULL OR agent_id=ANY(seen) OR cardinality(seen)>=64
    OR terms->>'club_id' IS DISTINCT FROM p_club_id::text OR terms->>'status' IS DISTINCT FROM 'active'
    OR terms->>'role' IS NULL OR terms->>'role' NOT IN('super_agent','agent','sub_agent')
   THEN RAISE EXCEPTION 'cash_commission_hierarchy_invalid_at_earning' USING ERRCODE='23514'; END IF;
   seen:=array_append(seen,agent_id);
   rate:=(terms->>'commission_rate')::numeric;
   IF rate>1 THEN rate:=rate/100; END IF;
   IF rate IS NULL OR rate<0 OR rate>1 OR rate::text IN('NaN','Infinity','-Infinity')
   THEN RAISE EXCEPTION 'cash_commission_rate_invalid_at_earning' USING ERRCODE='23514'; END IF;
   -- Preserve the installed agreement model: each upline rate applies to the
   -- remaining rake after the preceding tier. Round each payable to cents.
   amount:=round(remaining*rate,2);
   chain:=chain||jsonb_build_array(jsonb_build_object('agent_id',agent_id,'user_id',agent_user,
    'role',terms->>'role','depth',cardinality(seen),'rake_basis',p_rake,'remaining_basis',remaining,
    'rate',rate,'amount',amount,'agreement',agent));
   remaining:=remaining-amount;
   parent_id:=NULLIF(terms->>'parent_agent_id','')::uuid;
   IF parent_id IS NULL THEN agent:=NULL; ELSE agent:=public.fn_accounting_terms_at('agents',parent_id::text,p_terms_at); END IF;
  END LOOP;
 RETURN jsonb_build_object('player_id',p_player_id,'club_id',p_club_id,'union_id',p_game_union_id,
  'coordinator_union_id',coordinator_union,'rake_credit',p_rake,'membership',member,'tiers',chain,
  'club_residual',remaining,'union_agreement',union_agreement,'is_union_house',union_house,'terms_at',p_terms_at);
END $function$

CREATE OR REPLACE FUNCTION public.fn_accounting_tournament_commission_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$DECLARE s record;matches int;BEGIN
 IF NEW.source_type='tournament_fee_accrual' THEN
  SELECT f.*,r.recognized_at,r.disposition,b.status accounting_status INTO s FROM public.accounting_tournament_fee_sources f
   JOIN public.accounting_tournament_recognized_sources r ON r.source_id=f.id
   JOIN public.accounting_tournament_fee_recognitions b ON b.tournament_id=r.tournament_id WHERE f.id=NEW.source_id;
  IF NOT FOUND OR s.disposition IS DISTINCT FROM 'earned' OR s.accounting_status IS DISTINCT FROM 'recognized'
   OR NEW.club_id IS DISTINCT FROM s.club_id OR NEW.created_at IS DISTINCT FROM s.recognized_at THEN
   RAISE EXCEPTION 'tournament_commission_recognized_source_required' USING ERRCODE='23514'; END IF;
  SELECT count(*) INTO matches FROM jsonb_array_elements(s.contract->'tiers')t
   WHERE t->>'user_id'=NEW.user_id::text AND (t->>'amount')::numeric=NEW.amount AND (t->>'rate')::numeric=NEW.commission_rate AND NEW.amount>0;
  IF matches<>1 THEN RAISE EXCEPTION 'tournament_commission_disagrees_with_recorded_entitlement' USING ERRCODE='23514'; END IF;
 ELSIF NEW.source_type IN('tournament_fee','tournament_rake_settlement') THEN
  RAISE EXCEPTION 'tournament_commission_requires_canonical_source_writer' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION public.fn_accounting_tournament_fee_net_plan(p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE refund_row record;raw_total numeric;positive_total numeric;refunded_total numeric:=0;expected numeric;raw_reference_sum numeric;
 positive_ids uuid[];negative_ids uuid[];processed uuid[]:='{}';refunded uuid[]:='{}';refs uuid[];direct_positive uuid[];
 pending uuid[];new_refunds uuid[];nested uuid[];covered uuid[];ref uuid;covered_ref uuid;
 refund_map jsonb:='{}';progress boolean;actual_union uuid;scope_count int;active_ids uuid[];refunded_ids uuid[];fingerprint text;
BEGIN
 IF p_tournament_id IS NULL THEN RAISE EXCEPTION 'tournament_required' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM public.rake_records r WHERE r.tournament_id=p_tournament_id AND r.is_tournament
   AND (r.rake_amount IS NULL OR r.rake_amount<>round(r.rake_amount,2) OR r.rake_amount::text IN('NaN','Infinity','-Infinity') OR r.hand_id IS NOT NULL)) THEN
  RAISE EXCEPTION 'tournament_fee_source_invalid' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(array_agg(id ORDER BY id) FILTER(WHERE rake_amount>0),'{}'),
  COALESCE(array_agg(id ORDER BY id) FILTER(WHERE rake_amount<0),'{}'),COALESCE(sum(rake_amount),0),COALESCE(sum(rake_amount) FILTER(WHERE rake_amount>0),0)
 INTO positive_ids,negative_ids,raw_total,positive_total FROM public.rake_records WHERE tournament_id=p_tournament_id AND is_tournament;
 IF raw_total<0 THEN RAISE EXCEPTION 'tournament_fee_net_negative' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM public.rake_records r LEFT JOIN public.accounting_tournament_fee_batches b ON b.rake_record_id=r.id
   WHERE r.id=ANY(positive_ids) AND ((b.status IS DISTINCT FROM 'captured' AND NOT public.fn_accounting_mixed_cutover_spin_proof_valid(b.rake_record_id)) OR b.tournament_id IS DISTINCT FROM p_tournament_id
    OR b.source_fingerprint IS DISTINCT FROM public.fn_accounting_tournament_fee_fingerprint(r)
    OR b.rake_amount IS DISTINCT FROM r.rake_amount
    OR b.rake_amount IS DISTINCT FROM (SELECT sum(s.rake_credit) FROM public.accounting_tournament_fee_sources s WHERE s.rake_record_id=r.id))) THEN
  RAISE EXCEPTION 'tournament_fee_sources_require_reconciliation' USING ERRCODE='55000'; END IF;
 IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources s WHERE s.tournament_id=p_tournament_id AND NOT(s.rake_record_id=ANY(positive_ids))) THEN
  RAISE EXCEPTION 'tournament_fee_source_scope_changed' USING ERRCODE='23514'; END IF;
 SELECT count(DISTINCT COALESCE(union_id::text,'private')),(array_agg(union_id))[1] INTO scope_count,actual_union
  FROM public.accounting_tournament_fee_sources WHERE tournament_id=p_tournament_id;
 IF scope_count>1 THEN RAISE EXCEPTION 'tournament_fee_game_scope_changed' USING ERRCODE='23514'; END IF;
 pending:=negative_ids;
 WHILE cardinality(pending)>0 LOOP
  progress:=false;
  FOR refund_row IN SELECT * FROM public.rake_records WHERE id=ANY(pending) ORDER BY created_at,id LOOP
   IF refund_row.source NOT IN('fn_unregister_from_tournament','atomic_cancel_tournament') THEN
    RAISE EXCEPTION 'tournament_fee_refund_source_unsupported' USING ERRCODE='55000'; END IF;
   IF refund_row.metadata ? 'original_rake_record_ids' AND jsonb_typeof(refund_row.metadata->'original_rake_record_ids')='array' THEN
    SELECT array_agg(value::uuid ORDER BY value) INTO refs FROM jsonb_array_elements_text(refund_row.metadata->'original_rake_record_ids');
   ELSIF refund_row.metadata ? 'original_rake_record_id' THEN refs:=ARRAY[(refund_row.metadata->>'original_rake_record_id')::uuid];
   ELSE RAISE EXCEPTION 'tournament_fee_refund_source_ids_missing' USING ERRCODE='23514'; END IF;
   IF refs IS NULL OR cardinality(refs)=0 OR cardinality(refs)<>(SELECT count(DISTINCT x) FROM unnest(refs)x)
    OR refund_row.id=ANY(refs) OR EXISTS(SELECT 1 FROM unnest(refs)x WHERE NOT(x=ANY(positive_ids||negative_ids))) THEN
    RAISE EXCEPTION 'tournament_fee_refund_source_ids_invalid' USING ERRCODE='23514'; END IF;
   SELECT COALESCE(array_agg(id) FILTER(WHERE rake_amount>0),'{}'),COALESCE(array_agg(id) FILTER(WHERE rake_amount<0),'{}'),sum(rake_amount)
    INTO direct_positive,nested,raw_reference_sum FROM public.rake_records WHERE id=ANY(refs);
   IF NOT(nested<@processed) THEN CONTINUE; END IF;
   covered:='{}';
   FOREACH ref IN ARRAY nested LOOP
    FOR covered_ref IN SELECT value::uuid FROM jsonb_array_elements_text(refund_map->ref::text) LOOP
     covered:=array_append(covered,covered_ref);
    END LOOP;
   END LOOP;
   IF NOT(covered<@direct_positive) THEN RAISE EXCEPTION 'tournament_fee_refund_dependency_incomplete' USING ERRCODE='23514'; END IF;
   IF EXISTS(SELECT 1 FROM unnest(direct_positive)x WHERE x=ANY(refunded) AND NOT(x=ANY(covered))) THEN
    RAISE EXCEPTION 'tournament_fee_refund_duplicates_prior_refund' USING ERRCODE='23514'; END IF;
   SELECT COALESCE(array_agg(x ORDER BY x),'{}') INTO new_refunds FROM unnest(direct_positive)x WHERE NOT(x=ANY(refunded));
   SELECT COALESCE(sum(rake_amount),0) INTO expected FROM public.rake_records WHERE id=ANY(new_refunds);
   IF expected<=0 OR expected IS DISTINCT FROM -refund_row.rake_amount OR raw_reference_sum IS DISTINCT FROM expected
    OR EXISTS(SELECT 1 FROM public.rake_records q WHERE q.id=ANY(refs) AND (q.club_id IS DISTINCT FROM refund_row.club_id
      OR (q.metadata->>'user_id' IS DISTINCT FROM refund_row.metadata->>'user_id')
      OR q.created_at>refund_row.created_at)) THEN
    RAISE EXCEPTION 'tournament_fee_refund_not_exact_full_sources' USING ERRCODE='23514'; END IF;
   -- A player refund needs its immutable unregistration or cancellation witness.
   -- Spin unwind uses the cancellation's exact reversal-id list and zero net.
   IF refund_row.source='fn_unregister_from_tournament' THEN
    IF NOT EXISTS(SELECT 1 FROM public.tournament_unregistration_receipts u WHERE u.tournament_id=p_tournament_id
      AND refund_row.id=ANY(u.fee_reversal_ids) AND refs<@u.fee_source_rake_record_ids
      AND u.user_id::text=refund_row.metadata->>'user_id') THEN
     RAISE EXCEPTION 'tournament_fee_refund_receipt_missing' USING ERRCODE='23514'; END IF;
   ELSE
    IF NOT EXISTS(SELECT 1 FROM public.tournament_cancellation_receipts c WHERE c.tournament_id=p_tournament_id
      AND refund_row.id=ANY(c.fee_reversal_ids) AND c.total_rake_after=0 AND c.fees_reversed=c.total_rake_before) THEN
     RAISE EXCEPTION 'tournament_fee_cancellation_receipt_missing' USING ERRCODE='23514'; END IF;
   END IF;
   refunded:=refunded||new_refunds;refunded_total:=refunded_total+expected;
   refund_map:=refund_map||jsonb_build_object(refund_row.id::text,to_jsonb(direct_positive));
   processed:=array_append(processed,refund_row.id);pending:=array_remove(pending,refund_row.id);progress:=true;
  END LOOP;
  IF NOT progress THEN RAISE EXCEPTION 'tournament_fee_refund_dependency_cycle' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF positive_total-refunded_total IS DISTINCT FROM raw_total THEN
  RAISE EXCEPTION 'tournament_fee_net_not_conserved' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(array_agg(id ORDER BY id) FILTER(WHERE NOT(rake_record_id=ANY(refunded))),'{}'),
  COALESCE(array_agg(id ORDER BY id) FILTER(WHERE rake_record_id=ANY(refunded)),'{}')
 INTO active_ids,refunded_ids FROM public.accounting_tournament_fee_sources WHERE tournament_id=p_tournament_id;
 SELECT md5(COALESCE(string_agg(public.fn_accounting_tournament_fee_fingerprint(r),':' ORDER BY r.id),'')) INTO fingerprint
  FROM public.rake_records r WHERE tournament_id=p_tournament_id AND is_tournament;
 RETURN jsonb_build_object('accounting_version',2,'status','proven','tournament_id',p_tournament_id,
  'source_fingerprint',fingerprint,'union_id',actual_union,'gross_fee',positive_total,'refunded_fee',refunded_total,
  'net_fee',raw_total,'active_source_ids',active_ids,'refunded_source_ids',refunded_ids,'payable',false);
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_autoledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  spec text; col text; acct text;
  o jsonb; nn jsonb;
  d numeric; oldv numeric; newv numeric;
  cat text; cp text; cpid uuid;
  v_club uuid; v_union uuid; v_entity uuid; v_guc_club uuid;
  actor uuid;
  v_st text; v_msg text;
BEGIN
  IF current_setting('app.ledger_autoskip_' || TG_TABLE_NAME, true) = '1' THEN
    RETURN NEW;
  END IF;

  o  := CASE WHEN TG_OP = 'INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
  nn := to_jsonb(NEW);

  cat := COALESCE(NULLIF(current_setting('app.ledger_category', true), ''), 'adjustment');
  cp  := COALESCE(NULLIF(current_setting('app.ledger_counterparty', true), ''), 'settlement_suspense');
  BEGIN
    cpid := NULLIF(current_setting('app.ledger_counterparty_entity', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN cpid := NULL;
  END;
  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);

  /* THE JOURNAL LEG NAMES THE CLUB THE MONEY LANDED IN (2026-09-20).
     union_wallets and unions are the only autoledgered tables with no
     club_id column - `nn ? 'club_id'` is key EXISTENCE, so a table
     that has the column takes the arm above even when it is NULL. Before
     today every leg journalled from those two was written club-less, and
     fn_chip_drift_since_baseline filters movements on club_id IS NOT
     NULL while counting the balance they explain, so correctly paid
     union-hosted prizes were reported as member drift.
     A payer that knows the club declares it on
     app.ledger_autoledger_club_id, transaction-scoped, and clears it
     beside the autoskips. It is deliberately NOT app.ledger_club_id:
     that name is taken and decides which club a WALLET credit is paid
     into (atomic_credit_wallet_and_log, atomic_deduct_wallet_and_log,
     log_wallet_transaction), so borrowing it would let a rakeback
     close's club leak onto a union leg and would move real money when
     cleared. Read through an exception guard exactly as cpid is above:
     a malformed value must never abort a chip movement. */
  BEGIN
    v_guc_club := NULLIF(current_setting('app.ledger_autoledger_club_id', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN v_guc_club := NULL;
  END;
  v_club := CASE
    WHEN TG_TABLE_NAME = 'clubs' THEN (nn->>'id')::uuid
    WHEN nn ? 'club_id' THEN NULLIF(nn->>'club_id','')::uuid
    ELSE v_guc_club END;
  v_union := CASE
    WHEN TG_TABLE_NAME = 'unions' THEN (nn->>'id')::uuid
    WHEN nn ? 'union_id' THEN NULLIF(nn->>'union_id','')::uuid
    ELSE NULL END;
  v_entity := CASE
    WHEN TG_TABLE_NAME = 'agents' THEN NULLIF(nn->>'user_id','')::uuid
    WHEN TG_TABLE_NAME = 'club_members' THEN NULLIF(nn->>'user_id','')::uuid
    ELSE COALESCE(NULLIF(nn->>'id','')::uuid, v_club, v_union) END;

  FOR i IN 0 .. TG_NARGS - 1 LOOP
    spec := TG_ARGV[i];
    col  := split_part(spec, '=', 1);
    acct := split_part(spec, '=', 2);
    oldv := COALESCE(NULLIF(o->>col,'')::numeric, 0);
    newv := COALESCE(NULLIF(nn->>col,'')::numeric, 0);
    d := round(newv - oldv, 2);
    CONTINUE WHEN d = 0;

    BEGIN
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, union_id, description,
         pre_from_balance, post_from_balance, pre_to_balance, post_to_balance)
      VALUES (actor,
        CASE WHEN d > 0 THEN cp   ELSE acct END,
        CASE WHEN d > 0 THEN cpid ELSE v_entity END,
        CASE WHEN d > 0 THEN NULL ELSE TG_TABLE_NAME || '.' || col END,
        CASE WHEN d > 0 THEN acct ELSE cp END,
        CASE WHEN d > 0 THEN v_entity ELSE cpid END,
        CASE WHEN d > 0 THEN TG_TABLE_NAME || '.' || col ELSE NULL END,
        abs(d), cat, v_club, v_union,
        'auto-ledgered ' || TG_TABLE_NAME || '.' || col || ' delta ' || d::text,
        CASE WHEN d < 0 THEN oldv END, CASE WHEN d < 0 THEN newv END,
        CASE WHEN d > 0 THEN oldv END, CASE WHEN d > 0 THEN newv END);
    EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;
  END LOOP;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_begin_legacy_fee_resolution(p_tournament_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE o public.accounting_tournament_fee_custody_obligations%ROWTYPE;plan jsonb;raw record;
BEGIN
 SELECT * INTO o FROM public.accounting_tournament_fee_custody_obligations WHERE tournament_id=p_tournament_id;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_custody_resolutions WHERE tournament_id=p_tournament_id) THEN RETURN; END IF;
 PERFORM public.fn_ca_lock_settlement_lane_global();
 PERFORM 1 FROM public.tournaments WHERE id=p_tournament_id FOR NO KEY UPDATE;
 PERFORM 1 FROM public.tournament_escrow WHERE tournament_id=p_tournament_id FOR UPDATE;
 PERFORM public.fn_ca_tournament_terminal_receipt(p_tournament_id,NULL);
 INSERT INTO public.accounting_tournament_fee_custody_capture_admissions
  (tournament_id,obligation_id,source_fingerprint,amount)
 VALUES(p_tournament_id,o.id,o.source_fingerprint,o.amount);
 FOR raw IN SELECT r.id FROM public.rake_records r WHERE r.tournament_id=p_tournament_id
  AND r.is_tournament AND r.rake_amount>0
  AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches b WHERE b.rake_record_id=r.id)
  ORDER BY r.id LOOP
  PERFORM public.fn_ca_capture_tournament_fee_from_recorded_evidence(raw.id);
 END LOOP;
 plan:=public.fn_accounting_tournament_fee_net_plan(p_tournament_id);
 IF plan->>'status' IS DISTINCT FROM 'proven' OR plan->>'source_fingerprint' IS DISTINCT FROM o.source_fingerprint
  OR (plan->>'net_fee')::numeric IS DISTINCT FROM o.amount
  OR jsonb_array_length(plan->'active_source_ids')<1
  OR (public.fn_ca_sep8_spin_original_fee_proof(p_tournament_id) IS NOT NULL AND jsonb_array_length(plan->'active_source_ids')<>3)
 THEN RAISE EXCEPTION 'original fee continuation requires exact canonical attribution proof' USING ERRCODE='P0404'; END IF;
 INSERT INTO public.accounting_tournament_fee_custody_resolutions
  (tournament_id,obligation_id,amount,source_fingerprint,original_plan)
 VALUES(p_tournament_id,o.id,o.amount,o.source_fingerprint,plan);
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_capture_tournament_fee_from_recorded_evidence(p_rake_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r public.rake_records%ROWTYPE; t record; e record; l record; tp record;
  item jsonb; row_plan record; cutoff timestamptz; manifest jsonb;
  contributors jsonb := '[]'; actual_union uuid; expected_kind text;
  expected_entitlement text; expected_category text; source_type text;
  uid uuid; reg uuid; count_rows int; reserve_id uuid; fingerprint text;
  total_weight numeric := 0; total_cents bigint; floor_total bigint;
  remainder_cents bigint; credit numeric; allocated numeric := 0;
  contract jsonb; new_id uuid; result_ids uuid[] := '{}';
  seen_players uuid[] := '{}'; seen_entitlements uuid[] := '{}';
  player uuid; club uuid; registration uuid; ledger_id uuid;
  entitlement_id uuid; charged_at timestamptz; weight numeric;
BEGIN
  SELECT * INTO r FROM public.rake_records WHERE id = p_rake_record_id FOR UPDATE;
  IF NOT FOUND OR r.is_tournament IS DISTINCT FROM true OR r.tournament_id IS NULL
   OR r.hand_id IS NOT NULL OR r.rake_amount IS NULL OR r.rake_amount <= 0
   OR r.rake_amount <> round(r.rake_amount, 2) OR r.rake_amount::text IN ('NaN','Infinity','-Infinity')
  THEN RAISE EXCEPTION 'positive_chip_tournament_fee_required' USING ERRCODE = '23514'; END IF;

  -- The producer's own lock, so this can never race a live capture.
  PERFORM pg_advisory_xact_lock(hashtextextended('accounting_tournament_fee:'||r.id::text, 0));

  -- ENTRY CONDITIONS, narrower than the producer's in every direction.
  SELECT starts_at INTO cutoff FROM public.accounting_tournament_fee_cutover WHERE singleton;
  IF cutoff IS NULL THEN
    RAISE EXCEPTION 'fee_cutover_missing' USING ERRCODE = '55000'; END IF;
  IF r.created_at >= cutoff THEN
    RAISE EXCEPTION 'tournament_fee_is_the_producers_to_capture' USING ERRCODE = '55000',
      HINT = 'This record was charged at or after the cutover. Its own transaction owned its capture.'; END IF;
  IF EXISTS (SELECT 1 FROM public.accounting_tournament_fee_batches WHERE rake_record_id = r.id) THEN
    RAISE EXCEPTION 'tournament_fee_already_has_a_batch' USING ERRCODE = '23505'; END IF;

  SELECT id, club_id, union_id, is_private, tournament_type, status INTO t
    FROM public.tournaments WHERE id = r.tournament_id FOR SHARE;
  IF NOT FOUND OR public.fn_poker_diamond_tournament(r.tournament_id) THEN
    RAISE EXCEPTION 'chip_tournament_fee_required' USING ERRCODE = '23514'; END IF;
  -- A settled event's books are closed. This may only complete a live one.
  IF upper(COALESCE(t.status::text,'')) NOT IN ('RUNNING','BREAK','REGISTERING','COMPLETING')
   AND NOT public.fn_ca_legacy_fee_capture_admitted(r.tournament_id) THEN
    RAISE EXCEPTION 'tournament_fee_event_is_not_live' USING ERRCODE = '55000'; END IF;

  actual_union := CASE WHEN t.is_private THEN NULL ELSE t.union_id END;
  fingerprint  := public.fn_accounting_tournament_fee_fingerprint(r);

  -- EVIDENCE ASSEMBLY, byte for byte the rule fn_stamp_accounting_tournament_fee uses.
  IF r.source = 'fn_spin_book_entry' THEN
    IF jsonb_typeof(r.player_contributions) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(r.player_contributions)) <> 3 THEN
      RAISE EXCEPTION 'spin_fee_exact_paid_contributors_required' USING ERRCODE = '23514'; END IF;
    FOR item IN SELECT jsonb_build_object('player_id', key, 'weight', value)
                  FROM jsonb_each_text(r.player_contributions) ORDER BY key LOOP
      SELECT * INTO tp FROM public.tournament_players
       WHERE tournament_id = r.tournament_id AND user_id = (item->>'player_id')::uuid;
      IF NOT FOUND OR tp.club_id IS NULL THEN
        RAISE EXCEPTION 'spin_fee_entry_club_missing' USING ERRCODE = '23514'; END IF;
      SELECT count(*) INTO count_rows FROM public.tournament_refund_entitlements x
       WHERE x.tournament_id = r.tournament_id AND x.user_id = (item->>'player_id')::uuid
         AND x.entitlement_kind = 'wallet_charge' AND x.charge_category = 'tournament_buyin'
         AND x.created_at = tp.registered_at AND x.gross = (item->>'weight')::numeric;
      IF count_rows <> 1 THEN
        RAISE EXCEPTION 'spin_fee_exact_charge_ambiguous' USING ERRCODE = '23514'; END IF;
      SELECT * INTO e FROM public.tournament_refund_entitlements x
       WHERE x.tournament_id = r.tournament_id AND x.user_id = (item->>'player_id')::uuid
         AND x.entitlement_kind = 'wallet_charge' AND x.charge_category = 'tournament_buyin'
         AND x.created_at = tp.registered_at AND x.gross = (item->>'weight')::numeric;
      contributors := contributors || jsonb_build_array(jsonb_build_object(
        'player_id', e.user_id, 'club_id', e.refund_wallet_club_id, 'registration_id', tp.id,
        'charge_ledger_id', e.source_ledger_id, 'entitlement_id', e.id,
        'charged_at', e.created_at, 'weight', (item->>'weight')::numeric));
    END LOOP;
    SELECT count(*) INTO count_rows FROM public.spin_reserve_ledger s
     WHERE s.tournament_id = r.tournament_id AND s.kind = 'contribution';
    IF count_rows <> 1 THEN
      RAISE EXCEPTION 'spin_fee_exact_reserve_required' USING ERRCODE = '23514'; END IF;
    SELECT id INTO reserve_id FROM public.spin_reserve_ledger s
     WHERE s.tournament_id = r.tournament_id AND s.kind = 'contribution';
  ELSE
    IF NOT COALESCE(r.metadata->>'user_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$', false) THEN
      RAISE EXCEPTION 'tournament_fee_exact_player_required' USING ERRCODE = '23514'; END IF;
    uid := (r.metadata->>'user_id')::uuid;
    expected_entitlement := CASE r.source
      WHEN 'fn_register_for_tournament' THEN 'wallet_charge'
      WHEN 'fn_register_horse_for_tournament' THEN 'wallet_charge'
      WHEN 'process_tournament_rebuy' THEN 'wallet_charge'
      WHEN 'fn_award_satellite_seat' THEN 'satellite_seat'
      WHEN 'fn_register_for_tournament_with_ticket' THEN 'tournament_ticket' END;
    expected_category := CASE WHEN r.source = 'process_tournament_rebuy' THEN 'rebuy' ELSE 'tournament_buyin' END;
    IF expected_entitlement IS NULL THEN
      RAISE EXCEPTION 'tournament_fee_source_unsupported' USING ERRCODE = '55000'; END IF;
    reg := NULLIF(r.metadata->>'registration_id','')::uuid;
    IF reg IS NULL AND r.source = 'process_tournament_rebuy' THEN
      SELECT id INTO reg FROM public.tournament_players
       WHERE tournament_id = r.tournament_id AND user_id = uid; END IF;
    IF reg IS NULL THEN
      RAISE EXCEPTION 'tournament_fee_exact_registration_required' USING ERRCODE = '23514'; END IF;
    SELECT count(*) INTO count_rows FROM public.tournament_refund_entitlements x
     WHERE x.tournament_id = r.tournament_id AND x.user_id = uid AND x.created_at = r.created_at
       AND x.refund_fee = r.rake_amount AND x.entitlement_kind = expected_entitlement
       AND (CASE WHEN expected_entitlement = 'wallet_charge' THEN x.charge_category = expected_category
                 ELSE x.registration_id = reg END);
    IF count_rows <> 1 THEN
      RAISE EXCEPTION 'tournament_fee_exact_charge_ambiguous' USING ERRCODE = '23514'; END IF;
    SELECT * INTO e FROM public.tournament_refund_entitlements x
     WHERE x.tournament_id = r.tournament_id AND x.user_id = uid AND x.created_at = r.created_at
       AND x.refund_fee = r.rake_amount AND x.entitlement_kind = expected_entitlement
       AND (CASE WHEN expected_entitlement = 'wallet_charge' THEN x.charge_category = expected_category
                 ELSE x.registration_id = reg END);
    contributors := jsonb_build_array(jsonb_build_object(
      'player_id', e.user_id,
      -- 2026-09-20. A satellite seat's contributor club is the
      -- REGISTRATION's club: the club whose member actually played, and the
      -- only club for which fn_accounting_earning_contract resolves (149/149
      -- against 88/149 for the host club). fn_award_satellite_seat wrote
      -- refund_wallet_club_id as the HOST club until the 2026-09-17 cutover;
      -- that is a refund DESTINATION, not an earning scope, and it is
      -- verified as one in the evidence loop below. After the cutover the
      -- two are equal, so this changes nothing for a post-cutover record.
      'club_id', CASE WHEN e.entitlement_kind = 'satellite_seat'
                      THEN (SELECT x.club_id FROM public.tournament_players x WHERE x.id = reg)
                      ELSE e.refund_wallet_club_id END,
      'registration_id', reg,
      'charge_ledger_id', e.source_ledger_id, 'entitlement_id', e.id,
      'charged_at', e.created_at, 'weight', r.rake_amount));
  END IF;

  manifest := jsonb_build_object('union_id', actual_union, 'game_type', lower(t.tournament_type),
    'contributors', contributors, 'spin_reserve_id', reserve_id);

  -- EVIDENCE VERIFICATION, every check fn_capture_accounting_tournament_fee makes.
  -- The two provenance rules it applies are the only ones deliberately absent:
  -- the record need not have been created in this transaction, and a
  -- contributor's charge need not follow the cutover. Nothing else is relaxed.
  expected_kind := CASE r.source
    WHEN 'fn_register_for_tournament' THEN 'tournament_entry_fee'
    WHEN 'fn_register_horse_for_tournament' THEN 'tournament_entry_fee'
    WHEN 'fn_award_satellite_seat' THEN 'satellite_seat_entry_fee'
    WHEN 'fn_register_for_tournament_with_ticket' THEN 'tournament_ticket_entry_fee'
    WHEN 'fn_spin_book_entry' THEN 'spin_rake'
    WHEN 'process_tournament_rebuy' THEN r.metadata->>'kind' END;
  IF expected_kind IS NULL OR r.metadata->>'kind' IS DISTINCT FROM expected_kind
   OR (r.source = 'process_tournament_rebuy' AND expected_kind NOT IN ('tournament_rebuy_fee','tournament_reentry_fee'))
  THEN RAISE EXCEPTION 'tournament_fee_source_unsupported' USING ERRCODE = '55000'; END IF;

  count_rows := jsonb_array_length(manifest->'contributors');
  IF (r.source = 'fn_spin_book_entry' AND count_rows <> 3)
   OR (r.source <> 'fn_spin_book_entry' AND count_rows <> 1) THEN
    RAISE EXCEPTION 'tournament_fee_contributor_count_invalid' USING ERRCODE = '23514'; END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(manifest->'contributors') LOOP
    player := (item->>'player_id')::uuid; club := (item->>'club_id')::uuid;
    registration := (item->>'registration_id')::uuid; ledger_id := (item->>'charge_ledger_id')::uuid;
    entitlement_id := (item->>'entitlement_id')::uuid; charged_at := (item->>'charged_at')::timestamptz;
    weight := (item->>'weight')::numeric;
    IF player IS NULL OR club IS NULL OR registration IS NULL OR ledger_id IS NULL
     OR entitlement_id IS NULL OR charged_at IS NULL OR NOT isfinite(charged_at)
     OR charged_at > r.created_at
     OR weight IS NULL OR weight <= 0 OR weight <> round(weight,2)
     OR weight::text IN ('NaN','Infinity','-Infinity')
     OR player = ANY(seen_players) OR entitlement_id = ANY(seen_entitlements)
    THEN RAISE EXCEPTION 'tournament_fee_contributor_invalid' USING ERRCODE = '23514'; END IF;
    seen_players := array_append(seen_players, player);
    seen_entitlements := array_append(seen_entitlements, entitlement_id);

    SELECT * INTO e  FROM public.tournament_refund_entitlements WHERE id = entitlement_id;
    SELECT * INTO l  FROM public.chip_ledger WHERE id = ledger_id;
    SELECT * INTO tp FROM public.tournament_players WHERE id = registration;
    IF e.id IS NULL OR l.id IS NULL OR tp.id IS NULL
     OR e.tournament_id IS DISTINCT FROM r.tournament_id OR e.user_id IS DISTINCT FROM player
     OR (CASE WHEN e.entitlement_kind = 'satellite_seat'
              THEN e.refund_wallet_club_id IS DISTINCT FROM l.club_id
              ELSE e.refund_wallet_club_id IS DISTINCT FROM club END)
     OR e.source_ledger_id IS DISTINCT FROM ledger_id
     OR e.created_at IS DISTINCT FROM charged_at
     OR tp.tournament_id IS DISTINCT FROM r.tournament_id OR tp.user_id IS DISTINCT FROM player
     OR tp.club_id IS DISTINCT FROM club
     OR l.created_at IS DISTINCT FROM charged_at OR l.amount IS DISTINCT FROM e.gross
    THEN RAISE EXCEPTION 'tournament_fee_charge_evidence_mismatch' USING ERRCODE = '23514'; END IF;

    IF r.source = 'fn_spin_book_entry' THEN
      IF e.entitlement_kind IS DISTINCT FROM 'wallet_charge' OR e.charge_category IS DISTINCT FROM 'tournament_buyin'
       OR e.gross IS DISTINCT FROM weight OR l.from_type IS DISTINCT FROM 'player_wallet'
       OR l.from_entity_id IS DISTINCT FROM player OR l.to_type IS DISTINCT FROM 'prize_liability'
       OR l.to_entity_id IS DISTINCT FROM r.tournament_id OR l.club_id IS DISTINCT FROM club
       OR l.category IS DISTINCT FROM 'tournament_buyin'
       OR (r.player_contributions->>player::text)::numeric IS DISTINCT FROM weight
      THEN RAISE EXCEPTION 'spin_fee_charge_evidence_mismatch' USING ERRCODE = '23514'; END IF;
    ELSE
      IF e.refund_fee IS DISTINCT FROM r.rake_amount OR weight IS DISTINCT FROM r.rake_amount
       OR r.metadata->>'user_id' IS DISTINCT FROM player::text
      THEN RAISE EXCEPTION 'tournament_fee_amount_evidence_mismatch' USING ERRCODE = '23514'; END IF;
      IF r.source IN ('fn_register_for_tournament','fn_register_horse_for_tournament','process_tournament_rebuy') THEN
        source_type := CASE WHEN r.source = 'process_tournament_rebuy' THEN 'rebuy' ELSE 'tournament_buyin' END;
        IF e.entitlement_kind IS DISTINCT FROM 'wallet_charge' OR e.charge_category IS DISTINCT FROM source_type
         OR l.from_type IS DISTINCT FROM 'player_wallet' OR l.from_entity_id IS DISTINCT FROM player
         OR l.to_type IS DISTINCT FROM 'prize_liability' OR l.to_entity_id IS DISTINCT FROM r.tournament_id
         OR l.club_id IS DISTINCT FROM club OR l.category IS DISTINCT FROM source_type
         OR (r.source <> 'process_tournament_rebuy' AND r.metadata->>'registration_id' IS DISTINCT FROM registration::text)
        THEN RAISE EXCEPTION 'tournament_fee_wallet_evidence_mismatch' USING ERRCODE = '23514'; END IF;
      ELSIF r.source = 'fn_register_for_tournament_with_ticket' THEN
        IF e.entitlement_kind IS DISTINCT FROM 'tournament_ticket' OR e.registration_id IS DISTINCT FROM registration
         OR e.source_ticket_id IS NULL OR r.metadata->>'ticket_id' IS DISTINCT FROM e.source_ticket_id::text
         OR r.metadata->>'registration_id' IS DISTINCT FROM registration::text
         OR l.from_type IS DISTINCT FROM 'escrow' OR l.from_entity_id IS DISTINCT FROM e.source_ticket_id
         OR l.to_type IS DISTINCT FROM 'prize_liability' OR l.to_entity_id IS DISTINCT FROM r.tournament_id
         OR l.category IS DISTINCT FROM 'ticket_redeem'
        THEN RAISE EXCEPTION 'tournament_fee_ticket_evidence_mismatch' USING ERRCODE = '23514'; END IF;
      ELSE
        IF e.entitlement_kind IS DISTINCT FROM 'satellite_seat' OR e.registration_id IS DISTINCT FROM registration
         OR e.source_satellite_id IS NULL OR r.metadata->>'satellite_id' IS DISTINCT FROM e.source_satellite_id::text
         OR r.metadata->>'registration_id' IS DISTINCT FROM registration::text
         OR l.from_type IS DISTINCT FROM 'prize_liability' OR l.from_entity_id IS DISTINCT FROM e.source_satellite_id
         OR l.to_type IS DISTINCT FROM 'prize_liability' OR l.to_entity_id IS DISTINCT FROM r.tournament_id
         OR l.category IS DISTINCT FROM 'tournament_buyin'
        THEN RAISE EXCEPTION 'tournament_fee_satellite_evidence_mismatch' USING ERRCODE = '23514'; END IF;
      END IF;
    END IF;
    total_weight := total_weight + weight;
  END LOOP;

  IF r.source = 'fn_spin_book_entry' THEN
    IF (SELECT count(DISTINCT (x->>'weight')::numeric) FROM jsonb_array_elements(manifest->'contributors') x) <> 1
     OR NOT EXISTS (SELECT 1 FROM public.spin_reserve_ledger s
        WHERE s.id = (manifest->>'spin_reserve_id')::uuid AND s.tournament_id = r.tournament_id
          AND s.kind = 'contribution' AND s.seats = 3 AND s.house_rake = r.rake_amount
          AND s.amount = total_weight - r.rake_amount AND s.buy_in = total_weight/3)
    THEN RAISE EXCEPTION 'spin_fee_reserve_evidence_mismatch' USING ERRCODE = '23514'; END IF;
  END IF;

  -- ALLOCATION AND CONTRACT, the producer's arithmetic unchanged: largest
  -- remainder to whole cents, UUID order breaking exact fractional ties.
  total_cents := (r.rake_amount * 100)::bigint;
  SELECT sum(floor(total_cents * (x->>'weight')::numeric / total_weight)) INTO floor_total
    FROM jsonb_array_elements(manifest->'contributors') x;
  remainder_cents := total_cents - floor_total;

  INSERT INTO public.accounting_tournament_fee_batches
    (rake_record_id, tournament_id, source_fingerprint, rake_amount, source_manifest)
  VALUES (r.id, r.tournament_id, fingerprint, r.rake_amount,
    manifest || jsonb_build_object(
      'reconciled_at', transaction_timestamp(),
      'reconciled_by', 'fn_ca_reconcile_stranded_tournament_fee',
      'reconciliation_note', 'charged before the fee cutover; captured from its own recorded evidence'));

  FOR row_plan IN
    SELECT x, floor(total_cents * (x->>'weight')::numeric / total_weight)
      + CASE WHEN row_number() OVER (
          ORDER BY total_cents * (x->>'weight')::numeric / total_weight
            - floor(total_cents * (x->>'weight')::numeric / total_weight) DESC, x->>'player_id'
        ) <= remainder_cents THEN 1 ELSE 0 END AS cents
      FROM jsonb_array_elements(manifest->'contributors') x ORDER BY x->>'player_id'
  LOOP
    item := row_plan.x; credit := row_plan.cents / 100.0;
    contract := public.fn_accounting_earning_contract((item->>'club_id')::uuid,
      (item->>'player_id')::uuid, credit, actual_union, (item->>'charged_at')::timestamptz);
    IF contract->>'player_id' IS DISTINCT FROM item->>'player_id'
     OR contract->>'club_id' IS DISTINCT FROM item->>'club_id'
     OR (contract->>'rake_credit')::numeric IS DISTINCT FROM credit
     OR NULLIF(contract->>'union_id','')::uuid IS DISTINCT FROM actual_union
     OR (contract->>'terms_at')::timestamptz IS DISTINCT FROM (item->>'charged_at')::timestamptz
    THEN RAISE EXCEPTION 'tournament_fee_contract_scope_mismatch' USING ERRCODE = '23514'; END IF;
    INSERT INTO public.accounting_tournament_fee_sources
      (rake_record_id, tournament_id, player_id, club_id, union_id, coordinator_union_id,
       game_type, registration_id, source_charge_ledger_id, source_entitlement_id,
       charged_at, rake_credit, contract)
    VALUES (r.id, r.tournament_id, (item->>'player_id')::uuid, (item->>'club_id')::uuid, actual_union,
      NULLIF(contract->>'coordinator_union_id','')::uuid, manifest->>'game_type',
      (item->>'registration_id')::uuid, (item->>'charge_ledger_id')::uuid,
      (item->>'entitlement_id')::uuid, (item->>'charged_at')::timestamptz, credit, contract)
    RETURNING id INTO new_id;
    result_ids := array_append(result_ids, new_id);
    allocated := allocated + credit;
  END LOOP;

  IF allocated IS DISTINCT FROM r.rake_amount THEN
    RAISE EXCEPTION 'tournament_fee_credit_not_conserved' USING ERRCODE = '23514'; END IF;

  -- The plan's own test, applied to this record before the caller moves on.
  IF EXISTS (SELECT 1 FROM public.rake_records q
               JOIN public.accounting_tournament_fee_batches b ON b.rake_record_id = q.id
              WHERE q.id = r.id
                AND (b.status IS DISTINCT FROM 'captured'
                  OR b.tournament_id IS DISTINCT FROM r.tournament_id
                  OR b.source_fingerprint IS DISTINCT FROM public.fn_accounting_tournament_fee_fingerprint(q)
                  OR b.rake_amount IS DISTINCT FROM q.rake_amount
                  OR b.rake_amount IS DISTINCT FROM (SELECT sum(s.rake_credit)
                       FROM public.accounting_tournament_fee_sources s WHERE s.rake_record_id = q.id)))
  THEN RAISE EXCEPTION 'tournament_fee_reconciled_batch_would_not_satisfy_the_plan' USING ERRCODE = '23514'; END IF;

  INSERT INTO public.ca_stranded_fee_reconciliations
    (rake_record_id, tournament_id, rake_amount, contributor_count, source_ids, charged_at, cutover_at)
  VALUES (r.id, r.tournament_id, r.rake_amount, array_length(result_ids,1), result_ids, r.created_at, cutoff);

  RETURN jsonb_build_object('accounting_version', 2, 'status', 'captured', 'reconciled', true,
    'rake_record_id', r.id, 'tournament_id', r.tournament_id, 'source_ids', result_ids,
    'rake_credit', allocated, 'payable', false);
END
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_escrow_on_rake_settlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.settled_at IS NULL THEN RETURN NULL; END IF;
  IF TG_OP = 'UPDATE' AND OLD.settled_at IS NOT NULL THEN RETURN NULL; END IF;
  PERFORM public.fn_ca_escrow_apply(NEW.tournament_id, 'fee settlement', p_fee_out => round(COALESCE(NEW.amount, 0), 2));
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_tournament_fee_custody_receipt(p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE o public.accounting_tournament_fee_custody_obligations%ROWTYPE;
 e public.tournament_escrow%ROWTYPE;c record;fp text;net numeric;n integer;fees jsonb;resolution jsonb;resolved boolean:=false;funding jsonb;scope jsonb;
BEGIN
 SELECT * INTO o FROM public.accounting_tournament_fee_custody_obligations WHERE tournament_id=p_tournament_id;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO c FROM public.fn_ca_legacy_fee_custody_cohort(p_tournament_id);
 IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_custody_resolutions x WHERE x.tournament_id=p_tournament_id) THEN
  IF NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_recognitions x WHERE x.tournament_id=p_tournament_id AND x.status='recognized') THEN
   RAISE EXCEPTION 'fee custody resolution has no canonical recognition' USING ERRCODE='P0404'; END IF;
  resolution:=public.fn_accounting_tournament_terminal_fee_receipt(p_tournament_id);
  IF NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_custody_resolutions x
   WHERE x.tournament_id=p_tournament_id AND x.obligation_id=o.id AND x.amount=o.amount
    AND x.source_fingerprint=o.source_fingerprint AND (resolution->>'bank_amount')::numeric=x.amount
    AND (resolution->>'banked_at')::timestamptz=x.resolved_at AND resolution->>'status'='recognized') THEN
   RAISE EXCEPTION 'fee custody resolution has no exact original bank proof' USING ERRCODE='P0404'; END IF;
  resolved:=true;
 END IF;
 SELECT md5(COALESCE(string_agg(public.fn_accounting_tournament_fee_fingerprint(r),':' ORDER BY r.id),'')),
  COALESCE(sum(r.rake_amount),0),count(*),jsonb_agg(to_jsonb(r)-'terminal_closed_at' ORDER BY r.id)
 INTO fp,net,n,fees FROM public.rake_records r WHERE r.tournament_id=p_tournament_id AND r.is_tournament;
 SELECT * INTO e FROM public.tournament_escrow WHERE tournament_id=p_tournament_id;
 SELECT COALESCE(jsonb_agg(to_jsonb(x)-'terminal_closed_at' ORDER BY x.id),'[]'::jsonb) INTO funding
  FROM public.tournament_refund_entitlements x WHERE x.tournament_id=p_tournament_id;
 SELECT jsonb_build_object('club_id',t.club_id,'union_id',t.union_id,'is_private',t.is_private,'tournament_type',t.tournament_type)||CASE WHEN public.fn_ca_sep8_spin_original_fee_proof(p_tournament_id) IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('spin_original',public.fn_ca_sep8_spin_original_fee_proof(p_tournament_id)) END
  INTO scope FROM public.tournaments t WHERE t.id=p_tournament_id;
 IF c.amount IS NULL OR o.amount IS DISTINCT FROM c.amount OR net IS DISTINCT FROM c.amount
  OR fp IS DISTINCT FROM c.source_fingerprint OR fp IS DISTINCT FROM o.source_fingerprint
  OR n IS DISTINCT FROM c.source_count OR fees IS DISTINCT FROM o.original_fees
  OR funding IS DISTINCT FROM o.original_funding OR scope IS DISTINCT FROM o.original_scope
  OR e.tournament_id IS NULL OR e.prize_balance IS DISTINCT FROM 0::numeric
  OR e.bounty_balance IS DISTINCT FROM 0::numeric OR e.fee_balance IS DISTINCT FROM (CASE WHEN resolved THEN 0::numeric ELSE o.amount END)
  OR e.closed_at IS NOT NULL
  OR (to_jsonb(e)-ARRAY['terminal_closed_at','updated_at','fee_out','fee_balance']) IS DISTINCT FROM
     (o.escrow_snapshot-ARRAY['terminal_closed_at','updated_at','fee_out','fee_balance'])
  OR e.fee_out IS DISTINCT FROM ((o.escrow_snapshot->>'fee_out')::numeric+CASE WHEN resolved THEN o.amount ELSE 0 END)
  OR (NOT resolved AND (EXISTS(SELECT 1 FROM public.tournament_rake_settlements WHERE tournament_id=p_tournament_id)
   OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_recognitions WHERE tournament_id=p_tournament_id)
   OR EXISTS(SELECT 1 FROM public.accounting_tournament_recognized_sources WHERE tournament_id=p_tournament_id)))
 THEN RAISE EXCEPTION 'legacy fee custody no longer matches original conserved source' USING ERRCODE='P0404'; END IF;
 RETURN jsonb_build_object('accounting_version',3,'tournament_id',p_tournament_id,
  'status','fee_custody_unresolved','player_result','final','payable',false,'accounting_complete',resolved,
  'resolution',resolution,'current_held_amount',CASE WHEN resolved THEN 0 ELSE o.amount END,
  'obligation_id',o.id,'source_fingerprint',o.source_fingerprint,'source_count',n,
  'held_amount',o.amount,'held_at',o.held_at,'reason',o.reason,'custody_store','tournament_escrow',
  'recognized_source_count',0,'bank_amount',0,'banked_at',NULL,'bank_receipt_id',NULL);
END $function$

CREATE OR REPLACE FUNCTION public.fn_recognize_accounting_tournament_fees(p_tournament_id uuid, p_recognized_at timestamp with time zone, p_bank_club_id uuid, p_union_wallet_transaction_id uuid, p_bank_journal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE plan jsonb;prior record;source record;bank record;active_ids uuid[];refunded_ids uuid[];
 net_fee numeric;game_union uuid;rows_written int:=0;users_count int;source_count int;vip record;week_date date;
BEGIN
 IF p_recognized_at IS NULL OR p_recognized_at IS DISTINCT FROM transaction_timestamp() THEN
  RAISE EXCEPTION 'tournament_fee_original_recognition_transaction_required' USING ERRCODE='55000'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('accounting_tournament_recognition:'||p_tournament_id::text,0));
 PERFORM public.fn_lock_accounting_tournament_recognition_week(p_tournament_id,p_recognized_at);
 plan:=public.fn_accounting_tournament_fee_net_plan(p_tournament_id);
 SELECT * INTO prior FROM public.accounting_tournament_fee_recognitions WHERE tournament_id=p_tournament_id;
 IF FOUND THEN
  IF prior.source_fingerprint IS DISTINCT FROM plan->>'source_fingerprint' THEN
   RAISE EXCEPTION 'recognized_tournament_fee_sources_changed' USING ERRCODE='23514'; END IF;
  RETURN prior.plan||jsonb_build_object('status',prior.status,'payable',prior.status='recognized','replayed',true,'recognized_at',prior.recognized_at);
 END IF;
 net_fee:=(plan->>'net_fee')::numeric;game_union:=NULLIF(plan->>'union_id','')::uuid;
 IF p_bank_club_id IS NULL AND net_fee>0 THEN RAISE EXCEPTION 'tournament_fee_bank_club_required' USING ERRCODE='23514'; END IF;
 PERFORM public.fn_accounting_tournament_bank_proof(p_tournament_id,p_recognized_at,p_bank_club_id,game_union,net_fee,p_union_wallet_transaction_id,p_bank_journal_id);
 SELECT COALESCE(array_agg(value::uuid),'{}') INTO active_ids FROM jsonb_array_elements_text(plan->'active_source_ids');
 SELECT COALESCE(array_agg(value::uuid),'{}') INTO refunded_ids FROM jsonb_array_elements_text(plan->'refunded_source_ids');
 INSERT INTO public.accounting_tournament_fee_recognitions(tournament_id,recognized_at,status,net_rake,union_id,bank_club_id,
  union_wallet_transaction_id,bank_journal_id,source_fingerprint,plan)
 VALUES(p_tournament_id,p_recognized_at,CASE WHEN net_fee>0 THEN 'recognized' ELSE 'cancelled' END,net_fee,game_union,p_bank_club_id,
  p_union_wallet_transaction_id,p_bank_journal_id,plan->>'source_fingerprint',plan);
 INSERT INTO public.accounting_tournament_recognized_sources(source_id,tournament_id,recognized_at,disposition,rake_credit)
 SELECT s.id,p_tournament_id,p_recognized_at,CASE WHEN s.id=ANY(active_ids) THEN 'earned' ELSE 'refunded' END,
  CASE WHEN s.id=ANY(active_ids) THEN s.rake_credit ELSE 0 END
 FROM public.accounting_tournament_fee_sources s WHERE s.id=ANY(active_ids||refunded_ids);
 FOR source IN SELECT * FROM public.accounting_tournament_fee_sources WHERE id=ANY(active_ids) ORDER BY club_id,player_id,id LOOP
  rows_written:=rows_written+public.fn_post_accounting_commission_source(source.id,'tournament_fee_accrual',p_recognized_at,source.contract);
  -- Statistics use the real source record/player pair. The source credit is
  -- recognized once; a retry is guarded by the terminal recognition row above.
  PERFORM public.apply_rakeback_player_stats(source.rake_record_id,source.player_id,source.club_id,0,source.rake_credit);
 END LOOP;
 -- VIP already has a unique event/player source key. Preserve its original
 -- settlement-time grouping while giving it exact conserved contributor cents.
 FOR vip IN SELECT player_id,sum(rake_credit) credit FROM public.accounting_tournament_fee_sources
  WHERE id=ANY(active_ids) GROUP BY player_id ORDER BY player_id LOOP
  IF vip.credit>0 THEN PERFORM public.fn_award_vip_credit(vip.player_id,vip.credit,'tournament_rake',p_tournament_id,'Tournament rake generated'); END IF;
 END LOOP;
 week_date:=(public.fn_union_week_start(p_recognized_at) AT TIME ZONE 'America/Los_Angeles')::date;
 INSERT INTO public.accounting_period_recompute_requests(club_id,period_start,period_end,status)
 SELECT DISTINCT club_id,week_date,week_date+6,'pending' FROM public.accounting_tournament_fee_sources WHERE id=ANY(active_ids)
 ON CONFLICT(club_id,period_start,period_end) DO UPDATE SET status='pending',reason=NULL,last_result='{}'::jsonb,last_requested_at=transaction_timestamp();
 SELECT count(DISTINCT player_id),count(*) INTO users_count,source_count FROM public.accounting_tournament_fee_sources WHERE id=ANY(active_ids);
 RETURN plan||jsonb_build_object('status',CASE WHEN net_fee>0 THEN 'recognized' ELSE 'cancelled' END,
  'recognized_at',p_recognized_at,'payable',net_fee>0,'replayed',false,'commission_rows',rows_written,
  'attributed_users',users_count,'source_count',source_count,'attributed_chips',net_fee);
END $function$

CREATE OR REPLACE FUNCTION public.fn_satellite_transfer_ledger_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_source_ids uuid[] := ARRAY[]::uuid[];
  v_source_id uuid;
  v_target_id uuid;
  v_text text;
  v_row jsonb;
  v_status text;
BEGIN
  IF TG_OP<>'DELETE' AND public.fn_ca_legacy_fee_resolution_write_is_exact(TG_TABLE_NAME,TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE'
     AND (NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.from_entity_id IS DISTINCT FROM OLD.from_entity_id
       OR NEW.to_entity_id IS DISTINCT FROM OLD.to_entity_id
       OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
       OR (NEW.metadata->>'satellite_id') IS DISTINCT FROM
          (OLD.metadata->>'satellite_id')) THEN
    RAISE EXCEPTION 'satellite transfer journal ownership is immutable'
      USING ERRCODE = '55000';
  END IF;
  FOREACH v_row IN ARRAY ARRAY[
    CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END,
    CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END
  ] LOOP
    IF v_row IS NULL THEN CONTINUE; END IF;
    v_text := v_row->>'tournament_id';
    IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_source_ids := array_append(v_source_ids,v_text::uuid);
    END IF;
    IF v_row->>'from_type' = 'prize_liability' THEN
      v_text := v_row->>'from_entity_id';
      IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_source_ids := array_append(v_source_ids,v_text::uuid);
      END IF;
    END IF;
    v_text := split_part(COALESCE(v_row->>'idempotency_key',''),':',2);
    IF COALESCE(v_row->>'idempotency_key','') LIKE 'tourney:%:seat:%:pool_transfer'
       AND v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_source_ids := array_append(v_source_ids,v_text::uuid);
    END IF;
    v_text := v_row->'metadata'->>'satellite_id';
    IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_source_ids := array_append(v_source_ids,v_text::uuid);
    END IF;
  END LOOP;
  IF TG_OP <> 'INSERT' AND cardinality(v_source_ids) > 0 THEN
    RAISE EXCEPTION 'satellite transfer journal is append-only'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.to_type = 'prize_liability' THEN
    SELECT t.id INTO v_target_id FROM public.tournaments t
     WHERE t.id = NEW.to_entity_id;
    IF v_target_id IS NOT NULL THEN
      -- The transfer's AFTER trigger writes target escrow, so own the target
      -- before any source root exactly as fn_settle_satellite_tournament does.
      SELECT upper(COALESCE(t.status::text,'')) INTO v_status
        FROM public.tournaments t
       WHERE t.id = v_target_id FOR SHARE;
      IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
        RAISE EXCEPTION 'terminal target cannot accept a satellite transfer journal'
          USING ERRCODE = '55000';
      END IF;
    END IF;
  END IF;
  FOR v_source_id IN
    SELECT DISTINCT source.id FROM unnest(v_source_ids) source(id)
     WHERE source.id IS NOT NULL ORDER BY source.id
  LOOP
    IF TG_OP = 'INSERT' AND v_source_id IS DISTINCT FROM v_target_id THEN
      SELECT upper(COALESCE(t.status::text,'')) INTO v_status
        FROM public.tournaments t
       WHERE t.id = v_source_id FOR SHARE;
      IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
        RAISE EXCEPTION 'completed satellite transfer journal is immutable'
          USING ERRCODE = '55000';
      END IF;
    END IF;
    IF public.fn_ca_has_committed_tournament_receipt(v_source_id) THEN
      RAISE EXCEPTION 'completed satellite transfer journal is immutable'
        USING ERRCODE = '55000';
    END IF;
  END LOOP;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_settle_tournament_rake(p_tournament_id uuid, p_source text DEFAULT 'engine'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
 v_t record;v_prior record;v_claimed int;v_plan jsonb;v_att jsonb;v_res jsonb;
 v_net numeric;v_union uuid;v_dest text;v_reason text;v_raw record;v_bank_id uuid;v_journal_id uuid;v_matches int;
 v_week_start timestamptz;v_week_end timestamptz;v_lock_key text;v_attempt int:=0;
BEGIN
 PERFORM public.fn_ca_lock_settlement_lane_global();
 SELECT t.id,t.status,t.club_id,t.union_id,t.is_private,t.name,t.current_players INTO v_t
  FROM public.tournaments t WHERE t.id=p_tournament_id FOR NO KEY UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','not_found'); END IF;
 IF upper(COALESCE(v_t.status,'')) NOT IN('COMPLETING','COMPLETED','CANCELLED','CANCELED') THEN
  RETURN jsonb_build_object('ok',false,'reason','not_terminal','status',v_t.status); END IF;
 PERFORM public.fn_ca_begin_legacy_fee_resolution(p_tournament_id);
 INSERT INTO public.tournament_rake_settlements(tournament_id,club_id,amount,destination,source)
 VALUES(p_tournament_id,v_t.club_id,0,'pending',COALESCE(p_source,'engine')) ON CONFLICT(tournament_id) DO NOTHING;
 GET DIAGNOSTICS v_claimed=ROW_COUNT;
 IF v_claimed=0 THEN
  SELECT * INTO v_prior FROM public.tournament_rake_settlements WHERE tournament_id=p_tournament_id;
  -- Historical claims do not authorize another fee transfer or a success
  -- claim unless their stored attribution actually completed.
  IF v_prior.settled_at IS NULL OR v_prior.attributed_at IS NULL
   OR v_prior.attributed_users IS NULL OR v_prior.attributed_users<0
   OR v_prior.attribution_error IS NOT NULL
   OR NULLIF(v_prior.destination,'') IS NULL OR v_prior.destination='pending' THEN
   RETURN jsonb_build_object('ok',false,'already_settled',true,
    'reason','settlement_attribution_incomplete','amount',v_prior.amount,
    'destination',v_prior.destination,'settled_at',v_prior.settled_at,'attributed',false);
  END IF;
  IF v_prior.amount>0 AND v_prior.union_id IS NULL AND NOT public.fn_poker_diamond_tournament(p_tournament_id)
   AND v_prior.destination IS DISTINCT FROM 'chip_retirement:'||v_prior.club_id::text THEN
   RAISE EXCEPTION 'tournament_fee_legacy_treasury_leg_requires_adjustment' USING ERRCODE='55000'; END IF;
  v_att:=public.fn_accounting_tournament_terminal_fee_receipt(p_tournament_id);
  IF v_prior.amount>0 AND v_prior.union_id IS NULL AND NOT public.fn_poker_diamond_tournament(p_tournament_id) AND v_att IS NULL THEN
   RAISE EXCEPTION 'tournament_fee_disposition_receipt_missing' USING ERRCODE='55000'; END IF;
  RETURN jsonb_build_object('ok',true,'already_settled',true,'amount',v_prior.amount,'destination',v_prior.destination,
    'settled_at',v_prior.settled_at,'attributed',true,'attributed_users',v_prior.attributed_users,
    'no_attribution_due',v_prior.amount=0,'accounting',v_att);
 END IF;
  -- DIAMOND PHASE 8: a Diamond event's fee sits in its custody rows, not in
  -- rake_records; it goes to the house, and then the emptied custody closes.
  IF public.fn_poker_diamond_tournament(p_tournament_id) THEN
    v_res := public.fn_poker_diamond_tournament_settle_fee(p_tournament_id, COALESCE(p_source, 'engine'));
    v_net := COALESCE((v_res->>'amount')::numeric, 0);
    UPDATE public.tournament_rake_settlements
       SET amount = v_net,
           destination = CASE WHEN v_net > 0 THEN 'diamond_house' ELSE 'none' END,
           settled_at = now(), attributed_at = now(), attributed_users = 0
     WHERE tournament_id = p_tournament_id;
    v_res := public.fn_poker_diamond_tournament_close_custody(p_tournament_id);
    RETURN jsonb_build_object('ok', true, 'amount', v_net,
      'destination', CASE WHEN v_net > 0 THEN 'diamond_house' ELSE 'none' END,
      'attributed', true, 'attributed_users', 0, 'members', 0, 'asset', 'diamonds',
      'custody_closed', v_res->>'closed', 'custody_still_held', v_res->>'still_held');
  END IF;

 -- Deferred capture is normally already committed. A same-transaction Spin
 -- close still captures the original exact charge before it can be recognized.
 FOR v_raw IN SELECT r.id FROM public.rake_records r WHERE r.tournament_id=p_tournament_id AND r.is_tournament
  AND r.rake_amount>0 AND r.created_at=transaction_timestamp()
  AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches b WHERE b.rake_record_id=r.id) ORDER BY r.id LOOP
  PERFORM public.fn_stamp_accounting_tournament_fee(v_raw.id);
 END LOOP;
 -- 2026-09-20. A fee charged BEFORE the cutover was never captured by a
 -- producer, and fn_ca_capture_tournament_fee_from_recorded_evidence - the
 -- reader built for exactly that record - was reachable only from
 -- fn_ca_begin_legacy_fee_resolution, which does nothing unless the event
 -- already holds a custody obligation, which only a named event can get.
 -- So the reader was never called for an event that was not on a list.
 -- Call it here, on the ordinary close, while the event is COMPLETING.
 -- Each capture takes its own subtransaction: one that cannot prove itself
 -- rolls back alone and leaves its record exactly as it was, so the net
 -- plan below still refuses in the same words and legacy custody still
 -- receives the same reason. This can only add proof, never remove it.
 FOR v_raw IN SELECT r.id FROM public.rake_records r
   JOIN public.accounting_tournament_fee_cutover c ON c.singleton
  WHERE r.tournament_id=p_tournament_id AND r.is_tournament
    AND r.rake_amount>0 AND r.hand_id IS NULL AND r.created_at<c.starts_at
    AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches b WHERE b.rake_record_id=r.id)
  ORDER BY r.id LOOP
  BEGIN
   PERFORM public.fn_ca_capture_tournament_fee_from_recorded_evidence(v_raw.id);
  EXCEPTION WHEN OTHERS THEN
   -- Not silence: the reason travels to the log, and the refusal that
   -- follows is unchanged. "Could not prove it" is not "there was nothing".
   RAISE NOTICE 'pre-cutover fee % left uncaptured: % (%)', v_raw.id, SQLERRM, SQLSTATE;
  END;
 END LOOP;
 SELECT COALESCE(sum(r.rake_amount),0) INTO v_net FROM public.rake_records r WHERE r.tournament_id=p_tournament_id AND r.is_tournament;
 IF v_net<0 OR v_net<>round(v_net,2) OR v_net::text IN('NaN','Infinity','-Infinity') THEN
  RAISE EXCEPTION 'tournament_fee_net_invalid' USING ERRCODE='23514'; END IF;
 BEGIN
  -- Qualify only this owning close's complete original mixed-cutover Spin
  -- receipts. The original batch remains unchanged; any failure below rolls
  -- proof, source rows, claim, bank transfer and recognition back together.
  FOR v_raw IN SELECT r.id FROM public.rake_records r
   JOIN public.accounting_tournament_fee_batches b ON b.rake_record_id=r.id
   JOIN public.accounting_tournament_fee_cutover c ON c.singleton
   WHERE r.tournament_id=p_tournament_id AND r.is_tournament AND r.rake_amount>0
    AND r.source='fn_spin_book_entry' AND r.created_at>=c.starts_at
    AND b.status='legacy_unverified' AND b.source_manifest IS NULL ORDER BY r.id LOOP
   PERFORM public.fn_accounting_qualify_mixed_cutover_spin_fee(v_raw.id);
  END LOOP;
  v_plan:=public.fn_accounting_tournament_fee_net_plan(p_tournament_id);
 EXCEPTION WHEN SQLSTATE '55000' THEN
  IF SQLERRM NOT IN('tournament_fee_sources_require_reconciliation','accounting_terms_not_observed','accounting_terms_not_active','tournament_fee_not_captured_by_original_producer') THEN RAISE; END IF;
  v_reason:=SQLERRM;
  -- A new positive fee cannot leave custody before its exact attribution is
  -- available. Throw: direct callers must also roll back the inserted claim.
  IF v_net>0 THEN
   RAISE EXCEPTION 'tournament % rake attribution incomplete: %',p_tournament_id,v_reason USING ERRCODE='P0404';
  END IF;
  -- Exact zero owes no new attribution. Preserve the predecessor's zero-fee
  -- completion without inventing a source, bank, commission or paid receipt.
 END;
 v_union:=CASE WHEN v_reason IS NULL THEN NULLIF(v_plan->>'union_id','')::uuid
  WHEN v_t.is_private THEN NULL ELSE v_t.union_id END;
 PERFORM public.fn_lock_accounting_tournament_recognition_week(p_tournament_id,transaction_timestamp());
 -- A legacy event may have no captured contributor scope. Its actual bank
 -- still takes the exact same close lock, before either wallet is touched.
 v_week_start:=public.fn_union_week_start(transaction_timestamp());
 v_week_end:=((v_week_start AT TIME ZONE 'America/Los_Angeles')+interval '7 days') AT TIME ZONE 'America/Los_Angeles';
 v_lock_key:=CASE WHEN v_union IS NULL THEN 'club-accounting:'||v_t.club_id::text ELSE 'union-accounting:'||v_union::text END
  ||':'||extract(epoch FROM v_week_start)::text||':'||extract(epoch FROM v_week_end)::text;
 IF v_lock_key IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended(v_lock_key,0)); END IF;
 IF EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs x WHERE x.period_start<=transaction_timestamp() AND x.period_end>transaction_timestamp()
   AND ((v_union IS NOT NULL AND x.union_id=v_union) OR(v_union IS NULL AND x.standalone_club_id=v_t.club_id))) THEN
  RAISE EXCEPTION 'tournament_accrual_closed_period_requires_adjustment' USING ERRCODE='23514'; END IF;
 IF v_net>0 THEN
  IF v_t.club_id IS NULL THEN RAISE EXCEPTION 'tournament_fee_bank_club_required' USING ERRCODE='23514'; END IF;
  PERFORM 1 FROM public.club_wallets WHERE club_id=v_t.club_id FOR NO KEY UPDATE;
  PERFORM set_config('app.ledger_category','rake',true);
  PERFORM set_config('app.ledger_counterparty','prize_liability',true);
  PERFORM set_config('app.ledger_counterparty_entity',p_tournament_id::text,true);
  /* THE TOURNAMENT RAKE LEG NAMES THE CLUB IT WAS EARNED IN (2026-09-21).
     The union fee is routed by UPDATE-ing union_wallets.rake_wallet through
     increment_union_wallet; fn_ca_autoledger journals that delta, and
     union_wallets has no club_id column, so every tournament union rake leg
     was written club-less. 20260920192513 taught the autoledger to read a
     declaring payer and fixed the PRIZE legs; 20260921040847 made the
     cash-table rake payer declare; this is the tournament rake payer saying
     the same thing. v_t.club_id is refused NULL above, and is the same club
     handed to increment_union_wallet for union_wallet_transactions.club_id,
     so the leg and its sibling receipt name one club or the fee does not
     move at all. NOT app.ledger_club_id: that name decides which club a
     WALLET credit is paid into (atomic_credit_wallet_and_log) and is set and
     restored by the rakeback close, so clearing it here would move money. */
  PERFORM set_config('app.ledger_autoledger_club_id',COALESCE(v_t.club_id::text,''),true);
  IF v_union IS NOT NULL THEN
   v_res:=public.increment_union_wallet(v_union,v_net,v_t.club_id,
    'Tournament rake: '||COALESCE(v_t.name,'tournament')||' [tournament '||p_tournament_id::text||']');
   IF COALESCE((v_res->>'success')::boolean,false) IS NOT TRUE THEN RAISE EXCEPTION 'tournament_fee_union_credit_failed' USING ERRCODE='23514'; END IF;
   SELECT count(*),(array_agg(id))[1] INTO v_matches,v_bank_id FROM public.union_wallet_transactions
    WHERE union_id=v_union AND club_id=v_t.club_id AND wallet='rake_wallet' AND direction='credit' AND tx_type='rake'
     AND amount=v_net AND created_at=transaction_timestamp() AND position('[tournament '||p_tournament_id::text||']' IN COALESCE(notes,''))>0;
   v_dest:='union:'||v_union::text;
  ELSE
   -- The original settlement-row trigger removes this exact fee from escrow.
   -- Retire that liability in the canonical journal; never debit a treasury or
   -- call fn_ca_burn, which would take these same chips from a wallet again.
   UPDATE public.clubs SET total_rake=COALESCE(total_rake,0)+v_net,updated_at=now()
    WHERE id=v_t.club_id;
   IF NOT FOUND THEN RAISE EXCEPTION 'tournament_fee_club_missing' USING ERRCODE='23514'; END IF;
   INSERT INTO public.chip_ledger
    (performed_by,from_type,from_entity_id,to_type,to_entity_id,club_id,tournament_id,category,amount,description)
   VALUES(COALESCE(auth.uid(),'2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
    'prize_liability',p_tournament_id,'chip_retirement',NULL,v_t.club_id,p_tournament_id,'burn',v_net,
    'Standalone tournament fee retired (fn_settle_tournament_rake)') RETURNING id INTO v_journal_id;
   v_matches:=1;
   v_dest:='chip_retirement:'||v_t.club_id::text;
  END IF;
  IF v_matches<>1 THEN RAISE EXCEPTION 'tournament_fee_exact_bank_receipt_required' USING ERRCODE='23514'; END IF;
  UPDATE public.club_wallets SET period_rake_collected=COALESCE(period_rake_collected,0)+v_net,
   lifetime_rake_collected=COALESCE(lifetime_rake_collected,0)+v_net,updated_at=now() WHERE club_id=v_t.club_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'tournament_fee_club_wallet_missing' USING ERRCODE='23514'; END IF;
  PERFORM set_config('app.ledger_autoledger_club_id','',true);
 ELSE v_dest:='none'; END IF;
 IF v_reason IS NULL THEN
  -- Preserve the installed bounded retry contract, now around the sole
  -- canonical recognition writer. Exhaustion and permanent errors escape the
  -- whole settlement; rolled-back attempts cannot retain partial attribution.
  LOOP
   v_attempt:=v_attempt+1;
   BEGIN
    v_att:=public.fn_recognize_accounting_tournament_fees(p_tournament_id,transaction_timestamp(),v_t.club_id,v_bank_id,v_journal_id);
    EXIT;
   EXCEPTION WHEN deadlock_detected OR lock_not_available THEN
    IF v_attempt>=4 THEN RAISE; END IF;
    PERFORM pg_sleep(CASE v_attempt WHEN 1 THEN 0.1 WHEN 2 THEN 0.3 ELSE 0.6 END);
   END;
  END LOOP;
  IF v_att->>'status' IS DISTINCT FROM (CASE WHEN v_net>0 THEN 'recognized' ELSE 'cancelled' END)
   OR (v_att->>'attributed_chips')::numeric IS DISTINCT FROM v_net
   OR (v_net>0 AND COALESCE((v_att->>'attributed_users')::int,0)<1) THEN
   RAISE EXCEPTION 'tournament % rake attribution incomplete: canonical source receipt',p_tournament_id USING ERRCODE='P0404';
  END IF;
 END IF;
 UPDATE public.tournament_rake_settlements SET amount=v_net,union_id=v_union,destination=v_dest,settled_at=transaction_timestamp(),
  attributed_at=transaction_timestamp(),attributed_users=COALESCE((v_att->>'attributed_users')::int,0),
  attribution_error=NULL WHERE tournament_id=p_tournament_id;
 IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_custody_resolutions WHERE tournament_id=p_tournament_id AND transaction_id=txid_current()) THEN
  UPDATE public.tournament_rake_settlements SET terminal_closed_at=(SELECT completed_at FROM public.tournament_terminal_settlements WHERE tournament_id=p_tournament_id) WHERE tournament_id=p_tournament_id AND terminal_closed_at IS NULL;
 END IF;
 RETURN jsonb_build_object('ok',true,'amount',v_net,'destination',v_dest,'attributed',true,
  'attributed_users',COALESCE((v_att->>'attributed_users')::int,0),'attribution_attempts',v_attempt,
  'no_attribution_due',v_net=0,'accounting',public.fn_accounting_tournament_terminal_fee_receipt(p_tournament_id));
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_terminal_tournament_escrow_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_old_marker timestamptz;
  v_new_marker timestamptz;
  v_new_status text;
BEGIN
  IF TG_OP<>'DELETE' AND public.fn_ca_legacy_fee_resolution_write_is_exact(TG_TABLE_NAME,TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  IF TG_OP <> 'INSERT' THEN v_old_tournament_id := OLD.tournament_id; END IF;
  IF TG_OP <> 'DELETE' THEN v_new_tournament_id := NEW.tournament_id; END IF;
  IF TG_OP = 'UPDATE'
     AND v_new_tournament_id IS DISTINCT FROM v_old_tournament_id THEN
    RAISE EXCEPTION 'tournament escrow ownership is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' THEN v_old_marker := OLD.terminal_closed_at; END IF;
  IF TG_OP <> 'DELETE' THEN v_new_marker := NEW.terminal_closed_at; END IF;
  IF TG_OP = 'INSERT' AND v_new_marker IS NOT NULL THEN
    RAISE EXCEPTION 'new tournament escrow cannot supply a terminal marker'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' AND v_old_marker IS NOT NULL THEN
    RAISE EXCEPTION 'terminal tournament escrow evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker THEN
    IF public.fn_ca_terminal_marker_transition_is_exact(
         to_jsonb(OLD),to_jsonb(NEW),v_old_tournament_id) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'tournament escrow terminal marker transition is not canonical'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND v_new_tournament_id IS NOT NULL THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_new_status
      FROM public.tournaments t
     WHERE t.id = v_new_tournament_id FOR SHARE;
    IF v_new_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      RAISE EXCEPTION 'terminal tournament escrow evidence is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  IF public.fn_ca_has_committed_tournament_receipt(v_old_tournament_id)
     OR public.fn_ca_has_committed_tournament_receipt(v_new_tournament_id) THEN
    RAISE EXCEPTION 'terminal tournament escrow evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_terminal_tournament_evidence_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tournament_id uuid;
  v_status text;
  v_receipted boolean := false;
  v_old_marker timestamptz;
  v_new_marker timestamptz;
BEGIN
  IF TG_OP<>'DELETE' AND public.fn_ca_legacy_fee_resolution_write_is_exact(TG_TABLE_NAME,TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    v_tournament_id := NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid IS DISTINCT FROM
       NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid THEN
      RAISE EXCEPTION '% rows cannot move between tournaments',TG_TABLE_NAME
        USING ERRCODE = '55000';
    END IF;
    v_tournament_id := NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;
  ELSE
    v_tournament_id := NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;
  END IF;

  IF v_tournament_id IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP <> 'INSERT' AND to_jsonb(OLD) ? 'terminal_closed_at' THEN
    v_old_marker := NULLIF(to_jsonb(OLD)->>'terminal_closed_at','')::timestamptz;
  END IF;
  IF TG_OP <> 'DELETE' AND to_jsonb(NEW) ? 'terminal_closed_at' THEN
    v_new_marker := NULLIF(to_jsonb(NEW)->>'terminal_closed_at','')::timestamptz;
  END IF;
  IF TG_OP = 'INSERT' AND v_new_marker IS NOT NULL THEN
    RAISE EXCEPTION '% rows cannot supply a terminal marker',TG_TABLE_NAME
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' AND v_old_marker IS NOT NULL THEN
    RAISE EXCEPTION 'terminal tournament % has immutable % evidence',
      v_tournament_id,TG_TABLE_NAME USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker THEN
    IF public.fn_ca_terminal_marker_transition_is_exact(
         to_jsonb(OLD),to_jsonb(NEW),v_tournament_id) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION '% terminal marker transition is not canonical',TG_TABLE_NAME
      USING ERRCODE = '55000';
  END IF;
  -- A journal row is durable testimony from the instant it names a
  -- tournament. Refuse its UPDATE/DELETE without taking a child-to-parent
  -- lock; a row trigger already owns the child tuple at this point. INSERT is
  -- the only operation that takes the root lock, which preserves the
  -- parent-to-child order used by both terminal authorities.
  IF TG_TABLE_NAME = 'chip_ledger' AND TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'tournament chip ledger evidence is append-only'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_status
      FROM public.tournaments t
     WHERE t.id = v_tournament_id
     FOR SHARE;
  ELSE
    SELECT upper(COALESCE(t.status::text,'')) INTO v_status
      FROM public.tournaments t
     WHERE t.id = v_tournament_id;
  END IF;
  SELECT EXISTS (
           SELECT 1 FROM public.tournament_terminal_settlements h
            WHERE h.tournament_id = v_tournament_id)
      OR EXISTS (
           SELECT 1 FROM public.tournament_satellite_settlements h
            WHERE h.tournament_id = v_tournament_id)
      OR EXISTS (
           SELECT 1 FROM public.tournament_cancellation_receipts h
            WHERE h.tournament_id = v_tournament_id)
    INTO v_receipted;
  IF v_status IN ('COMPLETED','CANCELLED','CANCELED')
     AND (TG_OP = 'INSERT' OR v_receipted) THEN
    RAISE EXCEPTION
      'terminal tournament % has immutable % evidence',
      v_tournament_id,TG_TABLE_NAME USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.increment_union_wallet(p_union_id uuid, p_amount numeric, p_club_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_amount numeric; v_new_rake numeric;
BEGIN
  IF p_union_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'p_union_id required'); END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN RETURN jsonb_build_object('success', true, 'skipped', 'zero_amount'); END IF;
  v_amount := round(p_amount, 2);

  -- ZERO-DRIFT phase 2: declare the ledger category unless the caller
  -- already set one in this transaction (caller context is richer).
  IF COALESCE(current_setting('app.ledger_category', true), '') = '' THEN
    PERFORM set_config('app.ledger_category', 'rake', true);
    PERFORM set_config('app.ledger_counterparty', 'table_stack', true);
    PERFORM set_config('app.ledger_counterparty_entity', '', true);
  END IF;

  -- Rake Treasury only - see rake_lands_only_in_rake_treasury_not_union_bank.
  INSERT INTO public.union_wallets (union_id, chip_balance, rake_wallet, total_rake_collected)
       VALUES (p_union_id, 0, v_amount, v_amount)
  ON CONFLICT (union_id) DO UPDATE SET
       rake_wallet          = public.union_wallets.rake_wallet + v_amount,
       total_rake_collected = COALESCE(public.union_wallets.total_rake_collected, 0) + v_amount,
       updated_at           = NOW()
  RETURNING rake_wallet INTO v_new_rake;

  IF p_notes IS NOT NULL OR p_club_id IS NOT NULL THEN
    INSERT INTO public.union_wallet_transactions
      (union_id, club_id, amount, tx_type, wallet, direction, balance_after, notes)
    VALUES (p_union_id, p_club_id, v_amount, 'rake', 'rake_wallet', 'credit', v_new_rake,
            COALESCE(p_notes, 'Union rake credit'));
  END IF;

  RETURN jsonb_build_object('success', true, 'union_id', p_union_id, 'amount', v_amount,
                            'new_rake_wallet', v_new_rake);
END $function$

CREATE OR REPLACE FUNCTION smarter_private.spin_original_standings_witness(p_tournament uuid, p_winner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE r smarter_private.spin_original_standings%ROWTYPE; original jsonb; current_rows jsonb;
 original_busts jsonb; current_busts jsonb; winner jsonb; original_winner jsonb; candidate jsonb;
BEGIN
 SELECT * INTO r FROM smarter_private.spin_original_standings WHERE tournament_id=p_tournament;
 IF NOT FOUND THEN RETURN NULL; END IF;
 original:=r.expected->'snapshot';
 IF r.winner_id IS DISTINCT FROM p_winner OR r.expected_hash IS DISTINCT FROM md5(r.expected::text)
 OR original IS DISTINCT FROM smarter_private.spin_original_retained_case(p_tournament)
 OR (r.admitted_xid<>txid_current() AND NOT EXISTS(SELECT 1 FROM public.tournament_terminal_settlements WHERE tournament_id=p_tournament)) THEN
  RAISE EXCEPTION 'SPIN_ORIGINAL_WITNESS_IDENTITY' USING ERRCODE='P0404'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]') INTO current_rows FROM public.tournament_players p WHERE tournament_id=p_tournament;
 SELECT jsonb_agg(v ORDER BY v->>'id') INTO original_busts FROM jsonb_array_elements(original->'roster') v WHERE v->>'user_id'<>p_winner::text;
 SELECT jsonb_agg(v-'terminal_closed_at' ORDER BY v->>'id') INTO current_busts FROM jsonb_array_elements(current_rows) v WHERE v->>'user_id'<>p_winner::text;
 SELECT v INTO original_winner FROM jsonb_array_elements(original->'roster') v WHERE v->>'user_id'=p_winner::text;
 SELECT v INTO winner FROM jsonb_array_elements(current_rows) v WHERE v->>'user_id'=p_winner::text;
 candidate:=original->'candidates'->0;
 IF jsonb_array_length(current_rows)<>3 OR jsonb_array_length(original_busts)<>2
 OR current_busts IS DISTINCT FROM (SELECT jsonb_agg(v-'terminal_closed_at' ORDER BY v->>'id') FROM jsonb_array_elements(original_busts) v)
 OR (winner-ARRAY['status','position','prize','terminal_closed_at']) IS DISTINCT FROM (original_winner-ARRAY['status','position','prize','terminal_closed_at'])
 OR EXISTS(SELECT 1 FROM public.tournament_players p WHERE p.tournament_id=p_tournament
   AND p.terminal_closed_at IS DISTINCT FROM (SELECT completed_at FROM public.tournament_terminal_settlements WHERE tournament_id=p_tournament))
 OR winner->>'status' IS DISTINCT FROM 'winner' OR winner->'position' IS DISTINCT FROM '1'::jsonb
 OR winner->'chips' IS DISTINCT FROM '3000'::jsonb
 OR (winner->>'prize')::numeric NOT IN(0,(original->'tournament'->>'prize_pool')::numeric)
 OR (SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY id),'[]') FROM public.tournament_knockout_candidates c WHERE tournament_id=p_tournament) IS DISTINCT FROM original->'candidates'
 OR (SELECT to_jsonb(a) FROM public.hand_atomic_commits a WHERE hand_id=(candidate->>'hand_id')::uuid) IS DISTINCT FROM original->'atomic'->0
 OR (SELECT to_jsonb(h) FROM public.hand_history h WHERE id=(candidate->>'hand_id')::uuid) IS DISTINCT FROM original->'history'->0 THEN
  RAISE EXCEPTION 'SPIN_ORIGINAL_STANDINGS_CHANGED' USING ERRCODE='P0404'; END IF;
 RETURN jsonb_build_object('operation_id',r.operation_id,'expected_hash',r.expected_hash,
  'tournament_id',p_tournament,'winner_id',p_winner,'original_ranks',original_busts,
  'accepted_candidate',candidate,'accepted_hand_id',candidate->'hand_id',
  'accepted_hand_number',candidate->'hand_number','original_outcome','recorded_standings',
  'admitted_at',r.admitted_at);
END $function$
